{
        "corrected": "I am Karthik, and I have two years of experience in sales.",
        "mistakes": [
            {
                "wrong": "Myself Karthik",
                "right": "I am Karthik",
                "type": "grammar",
                "explanation_tamil": "தன்னுடைய பெயரை சொல்லும்போது 'Myself' பயன்படுத்தக்கூடாது."
            },
            {
                "wrong": "I am having",
                "right": "I have",
                "type": "style",
                "explanation_tamil": "அனுபவத்தைப் பற்றி பேசும்போது 'have' பயன்படுத்துவது தொழில்முறைக்கு சிறந்தது."
            }
        ]
    }

{
        "corrected": "I have been working at this company since 2019.","mistakes": [
            {
                "wrong": "am working",
                "right": "have been working","type": "grammar","explanation_tamil": "தொடர்ந்து நடக்கும் செயலுக்கு Present Perfect Continuous பயன்படுத்த வேண்டும்."
            },
            {
                "wrong": "in this company",
                "right": "at this company",
                "type": "style",
                "explanation_tamil": "நிறுவனத்தில் வேலை செய்வதைக் குறிக்க 'at' பயன்படுத்துவது தொழில்முறைக்கு சிறந்தது."
            }
        ]
    }

{
        "corrected": "Please revert to me today.",
        "mistakes": [
            {
                "wrong": "revert back",
                "right": "revert",
                "type": "grammar",
                "explanation_tamil": "revert-க்கு back தேவையில்லை."
            },
            {
                "wrong": "today itself",
                "right": "today",
                "type": "style",
                "explanation_tamil": "today itself என்பதை விட today போதுமானது."
            }
        ]
    }

{
        "corrected": "We discussed the budget, and he confirmed that it is fine.",
        "mistakes": [
            {
                "wrong": "discussed about",
                "right": "discussed",
                "type": "grammar",
                "explanation_tamil": "discuss-க்கு 'about' தேவையில்லை."
            },
            {
                "wrong": "he told that",
                "right": "he confirmed that",
                "type": "style",
                "explanation_tamil": "business-ல் 'told' என்பதைவிட 'confirmed' அல்லது 'stated' பயன்படுத்தலாம்."
            }
        ]
    }

